#!/usr/bin/env node
// Regenerates everything that is derived from data/. Run with: node tools/build.mjs
//
//   data/bundle.js          every data file in one request
//   exports/family-tree.ged the GEDCOM 7 export
//
// It validates first and refuses to build invalid data, so a broken tree cannot
// reach the generated files.
//
// Why a bundle: the page used to load one <script> per person. That is fine at
// 300 and hopeless at 10,000 — the browser opens a connection per file. The
// bundle is one request whatever the tree grows to. It stays a plain script,
// not a module or a fetch, so opening the page straight off disk still works.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(HERE, '..');

// The order the browser needs: configuration first, then the people.
export const CONFIG_FILES = ['meta.js', 'branches.js', 'lineages.js', 'groups.js', 'people.js'];

// Exported so the validator can rebuild this in memory and check the committed
// file still matches, which is what stops a stale bundle being committed.
export function buildBundle(root = ROOT) {
  const data = path.join(root, 'data');
  const parts = [
    '// GENERATED by tools/build.mjs — do not edit.',
    '// Every file in data/ concatenated, so the page needs one request instead',
    '// of one per person. Edit data/people/<id>.js and re-run the build.',
    '',
  ];
  for (const file of CONFIG_FILES) parts.push(fs.readFileSync(path.join(data, file), 'utf8').trim());
  const roster = readRoster(data);
  for (const id of roster) parts.push(fs.readFileSync(path.join(data, 'people', `${id}.js`), 'utf8').trim());
  return parts.join('\n') + '\n';
}

// people.js is a script that calls FamilyTree.roster([...]); the ids are read
// out of it rather than the directory, so the bundle order is the declared one.
export function readRoster(dataDir) {
  const src = fs.readFileSync(path.join(dataDir, 'people.js'), 'utf8');
  const inside = src.slice(src.indexOf('[') + 1, src.lastIndexOf(']'));
  return [...inside.matchAll(/"([^"]+)"/g)].map(m => m[1]);
}

// Run directly, rather than imported by the validator.
if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url))) {
  const check = spawnSync(process.execPath, [path.join(HERE, 'check-data.mjs'), '--skip-generated'], {
    stdio: 'inherit',
  });
  if (check.status !== 0) {
    console.error('\nValidation failed — nothing was generated.');
    process.exit(1);
  }

  const bundle = buildBundle();
  const out = path.join(ROOT, 'data', 'bundle.js');
  const before = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : null;
  fs.writeFileSync(out, bundle);
  const kb = (Buffer.byteLength(bundle) / 1024).toFixed(0);
  console.log(
    `\ndata/bundle.js — ${readRoster(path.join(ROOT, 'data')).length} people, ${kb} KB` +
      (before === bundle ? ' (unchanged)' : '')
  );

  const ged = spawnSync(process.execPath, [path.join(HERE, 'export-gedcom.mjs')], { stdio: 'inherit' });
  if (ged.status !== 0) process.exit(ged.status ?? 1);

  // The research log and the readable source list are generated the same way,
  // so a source added to the registry reaches docs/sources.md without a
  // separate step, and a log entry naming an unregistered source is caught here.
  const research = spawnSync(process.execPath, [path.join(HERE, 'research.mjs'), 'check'], { stdio: 'inherit' });
  if (research.status !== 0) process.exit(research.status ?? 1);
  spawnSync(process.execPath, [path.join(HERE, 'research.mjs'), 'docs'], { stdio: 'inherit' });
}
